insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_goal_oriented','goal-oriented','adjective','focused on achieving clear aims or results','[{"senseId":"goal_oriented_1","meaning":"focused on achieving clear aims or results","acceptedParaphrases":["focused on goals","aim-driven"],"masteryContexts":[{"contextId":"u1_21_goal_oriented_meaning","text":"The manager is goal-oriented: she cares less about how a task is done than about reaching the agreed result by Friday.","meaning":"strongly focused on specific results","wrongMeanings":["mainly interested in pleasing other people","careful to obey every rule","keen to share work equally with others"]},{"contextId":"u1_21_goal_oriented_paraphrase","text":"A goal-oriented runner writes a target time for each race and trains only in ways that will help reach it.","meaning":"directed toward achieving clear aims","wrongMeanings":["influenced by the opinions of friends","limited to a few exercises","decided by chance rather than planning"]}],"situationDistractors":["Our team plays only for fun and never keeps score.","She tries a different sport each week without any plan.","He often loses focus and thinks about other things.","The captain scored the winning goal in the final minute.","His team wandered across the pitch without a plan and quickly lost the ball.","He enjoys playing sport purely for fun, and he never keeps score or thinks about winning.","Our relaxed squad trains whenever it likes and never sets any real targets.","Younger pupils watched older students rehearsing the school musical after lessons.","Several students stayed after school to help clean the equipment room."],"gapDistractors":[{"contextId":"u1_21_goal_oriented_gap_meaning_sentence","answer":"goal-oriented","wrong":["careless","forgetful","disorganised"]},{"contextId":"u1_21_goal_oriented_gap_x2","answer":"goal-oriented","wrong":["distracted","careless","disorganised"]},{"contextId":"u1_21_goal_oriented_gap_x3","answer":"goal-oriented","wrong":["careless","forgetful","disorganised"]}],"spellingErrors":["goal-orriented","goal oriented","goaloriented","goal-orianted","goal-orientted","gole-oriented"],"masteryPassages":[{"passageId":"u1_21_goal_oriented_passage_1","contextId":"u1_21_goal_oriented_gap_meaning_sentence","text":"Our new manager is very ____. She sets clear targets at the start of every month and measures everything we do against them.","answer":"goal-oriented"},{"passageId":"u1_21_goal_oriented_passage_2","contextId":"u1_21_goal_oriented_gap_x1","text":"Some people drift through life. Others are ____ from a young age: they decide what they want to achieve and plan each step.","answer":"goal-oriented"}],"contextDependentParaphrases":[],"wrongParaphrases":["tired of trying","afraid of failing","happy to wait"],"misleadingDistractors":["easily distracted","casual","unplanned"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_achievement','achievement','noun','something important or difficult that has been successfully completed','[{"senseId":"achievement_1","meaning":"something important or difficult that has been successfully completed","acceptedParaphrases":["accomplishment","success"],"masteryContexts":[{"contextId":"u1_22_achievement_meaning","text":"Finishing the marathon in under four hours was a major achievement for someone who had only started running a year ago.","meaning":"worthwhile result gained through effort","wrongMeanings":["serious problem caused by lack of training","public award given for taking part","short rest taken during a long race"]},{"contextId":"u1_22_achievement_paraphrase","text":"The coach called her place on the national team the most difficult achievement of her career, because no one from the school had ever done it before.","meaning":"difficult success that has been completed","wrongMeanings":["difficult decision that has been delayed","lucky chance that happened purely by accident","unpleasant task that nobody will finish"]}],"situationDistractors":["He tried to finish the marathon but gave up at ten kilometres.","She trained every morning for months.","Her team lost the final after a poor performance.","The coach praised the players for being on time.","The club’s old changing rooms were damaged by heavy rain and closed for weeks.","Despite months of training, the player failed to finish the course and felt deeply disappointed.","The visiting team played very badly and went home without winning anything.","The visiting supporters waited patiently outside the stadium all morning.","A broken window delayed the opening of the new school gymnasium."],"gapDistractors":[{"contextId":"u1_22_achievement_gap_meaning_sentence","answer":"achievement","wrong":["injury","accident","disappointment"]},{"contextId":"u1_22_achievement_gap_x1","answer":"achievement","wrong":["disappointment","embarrassment","mistake"]},{"contextId":"u1_22_achievement_gap_x2","answer":"achievement","wrong":["injury","mistake","disappointment"]}],"spellingErrors":["acheivement","achievment","achievemant","acheivment","achivement","achievemnet"],"wordFamilyForms":[{"form":"achievement","partOfSpeech":"noun","example":"Completing the course in under an hour was a great achievement.","pedagogicallyUseful":true},{"form":"achieve","partOfSpeech":"verb","example":"What do you hope to achieve by the end of the season?","pedagogicallyUseful":true,"altExample":"Players who train every day can achieve far more than they expect."},{"form":"achievable","partOfSpeech":"adjective","example":"Set small goals that are achievable within a week.","pedagogicallyUseful":true,"altExample":"The coach set a goal that was difficult but achievable for the whole squad."}],"masteryPassages":[{"passageId":"u1_22_achievement_passage_1","contextId":"u1_22_achievement_gap_meaning_sentence","text":"Hana had been afraid of water all her life. Learning to swim at the age of forty was a remarkable ____ for her.","answer":"achievement"},{"passageId":"u1_22_achievement_passage_2","contextId":"u1_22_achievement_gap_x1","text":"At the end of the year, the school holds a celebration for every student. It recognises every kind of ____, from top exam results to improvement in sport.","answer":"achievement"}],"contextDependentParaphrases":[],"wrongParaphrases":["disappointment","attempt","routine"],"misleadingDistractors":["attempt","problem","routine"]}]'::jsonb,'["achieve","achievable"]'::jsonb,'["major achievement","sense of achievement"]'::jsonb,'live'),
('vocab_elite','elite','adjective','belonging to the highest level of ability or performance','[{"senseId":"elite_1","meaning":"belonging to the highest level of ability or performance","acceptedParaphrases":["top-level","highest-level"],"masteryContexts":[{"contextId":"u1_23_elite_meaning","text":"The elite squad is closed to all but the top one per cent of players in the country, chosen purely on results.","meaning":"among the very best in their field","wrongMeanings":["open to every player who applies","chosen mainly by the age of players","organised by the local school club"]},{"contextId":"u1_23_elite_paraphrase","text":"Entry to the elite competition is restricted to the top ten ranked players in the country, so most club players never qualify.","meaning":"at the top level of ability","wrongMeanings":["suitable for players of any ability","designed to teach basic skills slowly","held only once every four years"]}],"situationDistractors":["Beginners learn the basic rules in their first lesson.","Most students play sport once or twice a week for fun.","His club welcomes players of every age and level.","Young players practise in the park after school."],"gapDistractors":[{"contextId":"u1_23_elite_gap_x1","answer":"elite","wrong":["beginner","casual","recreational"]},{"contextId":"u1_23_elite_gap_x2","answer":"elite","wrong":["beginner","basic","casual"]},{"contextId":"u1_23_elite_gap_x3","answer":"elite","wrong":["casual","social","beginner"]}],"spellingErrors":["elit","eilte","ellite","elete","elyte","elitte"],"masteryPassages":[{"passageId":"u1_23_elite_passage_1","contextId":"u1_23_elite_gap_meaning_sentence","text":"Only a few hundred athletes in the whole country reach the ____ level. At this level they train full-time and compete for national teams.","answer":"elite"},{"passageId":"u1_23_elite_passage_2","contextId":"u1_23_elite_gap_x1","text":"Ordinary members of the club can use the pool at any time. The ____ swimmers, who train for the Olympics, have lanes reserved for them.","answer":"elite"}],"contextDependentParaphrases":[],"wrongParaphrases":["entry-level","beginner","average"],"misleadingDistractors":["average","beginner","local"]}]'::jsonb,'[]'::jsonb,'["elite athlete","elite level"]'::jsonb,'live'),
('vocab_overwhelming','overwhelming','adjective','so strong or great that it is difficult to manage or resist','[{"senseId":"overwhelming_1","meaning":"so strong or great that it is difficult to manage or resist","acceptedParaphrases":["very powerful","extremely strong"],"masteryContexts":[{"contextId":"u1_24_overwhelming_meaning","text":"The support from the home crowd was so overwhelming that the young players could hardly think or hear their coach.","meaning":"too powerful to manage easily","wrongMeanings":["too quiet to notice during the game","kind and encouraging for the whole team","organised carefully by the club officials"]},{"contextId":"u1_24_overwhelming_paraphrase","text":"Voters gave the new mayor an overwhelming majority, with more than ninety per cent supporting her.","meaning":"very large and clearly decisive","wrongMeanings":["small but still clearly noticeable","unclear until all votes are counted","changing as new results are announced"]}],"situationDistractors":["The noise from the crowd was quiet and easy to ignore.","A few people clapped politely after the final.","The crowd was slightly larger than last year.","The match was short and the weather was pleasant.","Their supporters left the stadium early because the slow, quiet game bored them.","Only a handful of spectators came to the match, so the stands looked almost completely empty.","Hardly anyone noticed the result, because the game finished late in the evening."],"gapDistractors":[{"contextId":"u1_24_overwhelming_gap_meaning_sentence","answer":"overwhelming","wrong":["weak","half-hearted","minimal"]},{"contextId":"u1_24_overwhelming_gap_x1","answer":"overwhelming","wrong":["optional","accidental","annual"]},{"contextId":"u1_24_overwhelming_gap_x2","answer":"overwhelming","wrong":["possible","optional","annual"]}],"spellingErrors":["overwelming","overwhelmeng","overwhleming","overwhellming","overwhealming","overwhelning"],"wordFamilyForms":[{"form":"overwhelming","partOfSpeech":"adjective","example":"The crowd gave the winners an overwhelming welcome.","pedagogicallyUseful":true},{"form":"overwhelm","partOfSpeech":"verb","example":"Too much homework can overwhelm even confident students.","pedagogicallyUseful":true},{"form":"overwhelmed","partOfSpeech":"adjective","example":"The young goalkeeper felt overwhelmed by the noise.","pedagogicallyUseful":true},{"form":"overwhelmingly","partOfSpeech":"adverb","example":"Students voted overwhelmingly for a longer lunch break.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_24_overwhelming_passage_1","contextId":"u1_24_overwhelming_gap_meaning_sentence","text":"The school asked students to vote on a new uniform. When the results were announced, the support for it was ____: nearly every student voted in favour.","answer":"overwhelming"},{"passageId":"u1_24_overwhelming_passage_2","contextId":"u1_24_overwhelming_gap_x1","text":"After moving to a huge city, Ali found the noise and the crowds ____ at first. It took him several weeks before he felt calm again.","answer":"overwhelming"}],"contextDependentParaphrases":[],"wrongParaphrases":["slightly boring","rather weak","fairly ordinary"],"misleadingDistractors":["boring","manageable","ordinary"]}]'::jsonb,'["overwhelm","overwhelmed","overwhelmingly"]'::jsonb,'[]'::jsonb,'live'),
('vocab_generation','generation','noun','a group of people born and living at roughly the same time','[{"senseId":"generation_1","meaning":"a group of people born and living at roughly the same time","acceptedParaphrases":["age group","people of the same era"],"masteryContexts":[{"contextId":"u1_25_generation_meaning","text":"People born in the nineties are often described as part of the same generation, because they grew up with similar technology.","meaning":"all who were born close together in time","wrongMeanings":["members of one large family living together","workers who share the same employer","students studying in the same class"]},{"contextId":"u1_25_generation_paraphrase","text":"A new generation of players, all born after the year 2005, is replacing the champions who dominated the sport for years.","meaning":"group born during a similar era","wrongMeanings":["team chosen to represent a country","group of experts who train players","series of games played in one season"]}],"situationDistractors":["A single player joined the team after the transfer window.","The old stadium was replaced by a modern one.","Several coaches left the club after a disagreement.","The league introduced a new set of rules this season.","Every player in the club wears the same red shirt for all home matches.","Shortly before the summer term began, the school bought brand new nets for the tennis courts.","The head coach divided the squad into equal teams for practice matches.","The council finally repaired the leaking roof above the indoor swimming pool."],"gapDistractors":[{"contextId":"u1_25_generation_gap_meaning_sentence","answer":"generation","wrong":["season","century","decade"]},{"contextId":"u1_25_generation_gap_x1","answer":"generation","wrong":["season","century","month"]},{"contextId":"u1_25_generation_gap_x2","answer":"generation","wrong":["season","century","month"]}],"spellingErrors":["genaration","generatoin","generasion","generetion","generaton","jeneration"],"masteryPassages":[{"passageId":"u1_25_generation_passage_1","contextId":"u1_25_generation_gap_meaning_sentence","text":"My grandparents’ ____ grew up without computers, while mine cannot imagine life without them. Each group has its own habits.","answer":"generation"},{"passageId":"u1_25_generation_passage_2","contextId":"u1_25_generation_gap_x1","text":"Football changes constantly. Every new ____ of players seems to be faster and fitter than the one before.","answer":"generation"}],"contextDependentParaphrases":[],"wrongParaphrases":["school class","family business","local audience"],"misleadingDistractors":["team","audience","committee"],"teacherNote":"Use the age-group sense here."}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_challenge','challenge','noun','a difficult task or situation that tests ability','[{"senseId":"challenge_1","meaning":"a difficult task or situation that tests ability","acceptedParaphrases":["difficult task","test"],"masteryContexts":[{"contextId":"u1_26_challenge_meaning","text":"The coach set the squad a challenge: to run ten kilometres without stopping, to see who could push their limits.","meaning":"difficulty that tests someone’s ability","wrongMeanings":["reward given for finishing a task","regulation explaining how a game is played","warning about a possible injury"]},{"contextId":"u1_26_challenge_paraphrase","text":"Playing the champions away from home will be a serious challenge for our young team, but we are ready to try.","meaning":"demanding problem requiring skill or effort","wrongMeanings":["friendly match played for enjoyment","chance to watch a famous team","lesson about how to control the ball"]}],"situationDistractors":["The final was easy and the team won without any effort.","The prize for the winner was a free membership.","Their coach explained the rules clearly to everyone.","The match was a routine game against a weak team.","The cheap trainers wore out after only two weeks of regular use.","Nobody found the first level hard, so the whole class moved on to the next topic early.","The new sports hall opened this week with a free swimming session.","His school canteen introduced cheaper meals for younger pupils."],"gapDistractors":[{"contextId":"u1_26_challenge_gap_meaning_sentence","answer":"challenge","wrong":["advantage","pleasure","benefit"]},{"contextId":"u1_26_challenge_gap_x1","answer":"challenge","wrong":["advantage","relief","bargain"]},{"contextId":"u1_26_challenge_gap_x2","answer":"challenge","wrong":["reward","holiday","timetable"]}],"spellingErrors":["chalenge","challange","chalenje","chalange","challege","chalengge"],"wordFamilyForms":[{"form":"challenge","partOfSpeech":"noun","example":"Climbing the mountain in winter was a serious challenge.","pedagogicallyUseful":true},{"form":"challenging","partOfSpeech":"adjective","example":"The coach designed a challenging programme for the advanced group.","pedagogicallyUseful":true,"altExample":"The mountain route was challenging, but the students enjoyed every minute."},{"form":"challenger","partOfSpeech":"noun","example":"The young challenger surprised the champion with an early lead.","pedagogicallyUseful":true,"altExample":"The young challenger surprised the champion with a fast start."}],"masteryPassages":[{"passageId":"u1_26_challenge_passage_1","contextId":"u1_26_challenge_gap_meaning_sentence","text":"A desert crossing is not for beginners. It is a huge ____, even for experienced walkers, because of the heat and the lack of water.","answer":"challenge"},{"passageId":"u1_26_challenge_passage_2","contextId":"u1_26_challenge_gap_x1","text":"The science teacher wanted the class to think creatively. She gave them an interesting ____: to build a bridge from paper that could hold a bag of rice.","answer":"challenge"}],"contextDependentParaphrases":[],"wrongParaphrases":["easy job","clear rule","small prize"],"misleadingDistractors":["reward","solution","routine"]}]'::jsonb,'["challenging","challenger"]'::jsonb,'["face a challenge","major challenge"]'::jsonb,'live'),
('vocab_solution','solution','noun','an answer to a problem or a way of dealing with a difficulty','[{"senseId":"solution_1","meaning":"an answer to a problem or a way of dealing with a difficulty","acceptedParaphrases":["answer","way to solve a problem"],"masteryContexts":[{"contextId":"u1_27_solution_meaning","text":"The club finally found a solution that ended the shortage of training space: it shared the school gym.","meaning":"method that resolves a difficulty","wrongMeanings":["reason why a difficulty keeps growing","complaint made about a lack of space","warning that a problem may return"]},{"contextId":"u1_27_solution_paraphrase","text":"One practical solution to the noise problem is to move the matches to the afternoon.","meaning":"workable way to fix a problem","wrongMeanings":["official rule that causes a problem","careful description of why something happened","angry reply to a repeated complaint"]}],"situationDistractors":["The shortage of balls caused the practice to be cancelled.","Nobody knew why the training sessions were so crowded.","The club argued about how to spend its money.","The shortage of space got worse every month.","Our coach was annoyed because several players had arrived late for training again.","The school pitch stayed closed all week, because nobody had cut the long grass for several months.","Several members complained that the changing rooms were cold, damp and unusually dirty.","Spectators queued patiently outside the stadium gates from early morning.","Parents received a letter about the changes to the school timetable."],"gapDistractors":[{"contextId":"u1_27_solution_gap_meaning_sentence","answer":"solution","wrong":["cause","complaint","penalty"]},{"contextId":"u1_27_solution_gap_x1","answer":"solution","wrong":["cause","complaint","penalty"]},{"contextId":"u1_27_solution_gap_x2","answer":"solution","wrong":["cause","excuse","complaint"]}],"spellingErrors":["solusion","solutoin","soloution","soluton","sollution","solucion"],"wordFamilyForms":[{"form":"solution","partOfSpeech":"noun","example":"The school found a simple solution to the problem of crowded changing rooms.","pedagogicallyUseful":true},{"form":"solve","partOfSpeech":"verb","example":"It took the engineers months to solve the problem of the leaking roof.","pedagogicallyUseful":true,"altExample":"Working together, the players managed to solve the problem of the muddy pitch."},{"form":"unsolved","partOfSpeech":"adjective","example":"The mystery of the missing trophy remained unsolved for years.","pedagogicallyUseful":true,"altExample":"The question of who would pay for the new nets remained unsolved.","note":"Participial adjective."}],"masteryPassages":[{"passageId":"u1_27_solution_passage_1","contextId":"u1_27_solution_gap_meaning_sentence","text":"The playground flooded every winter, and children could not use it for weeks. Then the council found a ____: a new drain under the field.","answer":"solution"},{"passageId":"u1_27_solution_passage_2","contextId":"u1_27_solution_gap_x1","text":"There was a mistake in the maths problem. No one in the class could find the ____, however hard they tried.","answer":"solution"}],"contextDependentParaphrases":[],"wrongParaphrases":["cause","argument","challenge"],"misleadingDistractors":["cause","argument","challenge"]}]'::jsonb,'["solve","unsolved"]'::jsonb,'["find a solution","practical solution"]'::jsonb,'live'),
('vocab_pastime','pastime','noun','an activity done regularly for enjoyment in your free time','[{"senseId":"pastime_1","meaning":"an activity done regularly for enjoyment in your free time","acceptedParaphrases":["hobby","leisure activity"],"masteryContexts":[{"contextId":"u1_28_pastime_meaning","text":"Collecting old coins is a popular pastime among retired people, who enjoy it in the afternoons.","meaning":"enjoyable activity done outside work","wrongMeanings":["paid job done after normal hours","school subject taught by a specialist","journey made for a special reason"]},{"contextId":"u1_28_pastime_paraphrase","text":"For many teenagers, playing video games is a favourite pastime, not a way of earning money.","meaning":"recreational pursuit for spare hours","wrongMeanings":["serious career chosen after training","regular duty carried out at home","skill required for a certain job"]}],"situationDistractors":["Football was her full-time job and she was paid to play.","He trained six hours a day to become a professional.","The sport was compulsory for every student at school.","Cycling was the main way he travelled to work.","The professional footballer trained six hours a day and treated football as his career.","Her team practised every single morning before school, because the national final was getting closer.","Her father worked as a full-time coach for the national swimming team.","Neighbours gathered along the main street to watch the colourful parade.","The older players prepared sandwiches for the long journey home."],"gapDistractors":[{"contextId":"u1_28_pastime_gap_meaning_sentence","answer":"pastime","wrong":["career","duty","subject"]},{"contextId":"u1_28_pastime_gap_x1","answer":"pastime","wrong":["profession","duty","uniform"]},{"contextId":"u1_28_pastime_gap_x2","answer":"pastime","wrong":["meal","season","festival"]}],"spellingErrors":["pasttime","pastim","pastyme","passtime","pasetime","pastimme"],"masteryPassages":[{"passageId":"u1_28_pastime_passage_1","contextId":"u1_28_pastime_gap_meaning_sentence","text":"My grandfather has never thought of gardening as work. Growing vegetables is a relaxing ____ that he enjoys every weekend.","answer":"pastime"},{"passageId":"u1_28_pastime_passage_2","contextId":"u1_28_pastime_gap_x1","text":"Reading used to be a popular ____ among teenagers. Now many prefer to spend their spare hours online.","answer":"pastime"}],"contextDependentParaphrases":[],"wrongParaphrases":["task","career","routine"],"misleadingDistractors":["career","duty","competition"]}]'::jsonb,'[]'::jsonb,'["popular pastime"]'::jsonb,'live'),
('vocab_feat','feat','noun','an impressive achievement that requires skill, strength, or courage','[{"senseId":"feat_1","meaning":"an impressive achievement that requires skill, strength, or courage","acceptedParaphrases":["remarkable achievement","impressive accomplishment"],"masteryContexts":[{"contextId":"u1_29_feat_meaning","text":"After two years of daily training, she completed the mountain run in under an hour, a feat that she had earned through practice rather than chance.","meaning":"notable act requiring unusual skill","wrongMeanings":["lucky result that nobody expected","serious mistake that took time to fix","long journey that tested everyone’s patience"]},{"contextId":"u1_29_feat_paraphrase","text":"Finishing the race with a broken ankle was a feat that earned the runner a standing ovation from the whole stadium.","meaning":"impressive accomplishment that is difficult","wrongMeanings":["reckless decision that endangered other runners","slow recovery after an injury","simple task that anyone could complete"]}],"situationDistractors":["Walking to the shop was something he did every day.","He made a small mistake at the start of the race.","The attempt to climb the mountain failed in bad weather.","Our team played an ordinary match on a weekday afternoon.","The goalkeeper made several small mistakes and conceded three very easy goals.","The swimmer stayed in bed all morning, and she decided to skip the important race altogether.","The inexperienced swimmers finished last in every heat and left disappointed.","Spectators complained loudly about the unexpectedly expensive refreshments inside the stadium."],"gapDistractors":[{"contextId":"u1_29_feat_gap_meaning_sentence","answer":"feat","wrong":["mistake","injury","accident"]},{"contextId":"u1_29_feat_gap_x1","answer":"feat","wrong":["injury","expense","delay"]},{"contextId":"u1_29_feat_gap_x2","answer":"feat","wrong":["failure","mistake","injury"]}],"spellingErrors":["feet","feit","feate","fiet","feeat","featt"],"masteryPassages":[{"passageId":"u1_29_feat_passage_1","contextId":"u1_29_feat_gap_meaning_sentence","text":"The lake was cold and almost a kilometre wide. Swimming across it alone was an extraordinary ____ for a ten-year-old, and the crowd on the shore cheered.","answer":"feat"},{"passageId":"u1_29_feat_passage_2","contextId":"u1_29_feat_gap_x1","text":"The robotics club had no money and no experience. Building a working robot from old parts was quite a ____ under those conditions.","answer":"feat"}],"contextDependentParaphrases":[],"wrongParaphrases":["serious mistake","daily routine","brief attempt"],"misleadingDistractors":["mistake","routine","attempt"]}]'::jsonb,'[]'::jsonb,'["remarkable feat"]'::jsonb,'live'),
('vocab_regardless','regardless','adverb','without being affected by a particular fact or situation','[{"senseId":"regardless_1","meaning":"without being affected by a particular fact or situation","acceptedParaphrases":["despite this","in any case"],"masteryContexts":[{"contextId":"u1_30_regardless_meaning","text":"The match will take place regardless of the weather, so bring waterproof clothes just in case.","meaning":"without letting that fact change things","wrongMeanings":["only after the weather has improved","depending on how bad the weather becomes","because the weather has been so bad"]},{"contextId":"u1_30_regardless_paraphrase","text":"Every student must attend training, regardless of their ability or experience, so beginners and the best players train together.","meaning":"despite the stated circumstance","wrongMeanings":["depending on each person’s circumstances","unless a teacher gives special approval","provided that everyone has equal ability"]}],"situationDistractors":["The match was cancelled because of the heavy rain.","The game would only go ahead if the weather was fine.","The race started late as a result of the rain.","Because the pitch was wet, the players stayed indoors.","The race was stopped halfway because of the heavy rain.","The match was cancelled because the pitch was too wet for anyone to play on it safely.","Nobody attended the final practice session.","The referee ended the match very early.","The pitch stayed closed for repairs.","Only two teams entered the cup this year.","Our goalkeeper changed his gloves before the second half."],"gapDistractors":[{"contextId":"u1_30_regardless_gap_meaning_sentence","answer":"regardless","wrong":["instead","apart","inside"]},{"contextId":"u1_30_regardless_gap_x1","answer":"regardless","wrong":["instead","apart","inside"]},{"contextId":"u1_30_regardless_gap_x2","answer":"regardless","wrong":["instead","apart","inside"]}],"spellingErrors":["regardles","regardlss","regaurdless","regardlass","regaredless","rigardless"],"masteryPassages":[{"passageId":"u1_30_regardless_passage_1","contextId":"u1_30_regardless_gap_meaning_sentence","text":"The forecast for Saturday is poor, but the organisers are not worried. The concert will go ahead ____ of the weather, so bring a coat.","answer":"regardless"},{"passageId":"u1_30_regardless_passage_2","contextId":"u1_30_regardless_gap_x1","text":"Everyone in the choir is welcome, ____ of age or experience. Some of our best singers had never sung before.","answer":"regardless"}],"contextDependentParaphrases":[],"wrongParaphrases":["because of this","only if","as a result"],"misleadingDistractors":["because of this","only if","as a result"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live')
